export const SUPPLEMENTAL_TRACK_ADDITIONS: Record<string, SupplementalMovieTrackPatch> = Object.fromEntries(
  Object.entries(RAW_PATCHES).map(([movieId, val]) => {
    const hasReplace = val.length === 2 && typeof val[0] === 'string';
    const replacePlaceholderId = hasReplace ? (val[0] as string) : undefined;
    const rawSongs = (hasReplace ? val[1] : val) as SongTuple[];
    const newSongs: SongEntry[] = rawSongs.map(([id, title, singers, ref, lyricist]) => ({
      id,
      movieId,
      title,
      singers,
      ...(lyricist ? { lyricist } : {}),
      adaptationType: 'original',
      originCategory: 'Original Composition',
      bollywoodLink: '',
      referenceSource: typeof ref === 'number' ? REF_MAP[ref] : ref,
    }));
    return [
      movieId,
      replacePlaceholderId ? { replacePlaceholderId, newSongs } : { newSongs },
    ];
  })
);
